fn test_the_words_of_every_enum_key_are_read() {
    let a: &mut crate::emon::enctx::Cfg = &mut crate::emon::enctx::Cfg::new();
    let b: &mut crate::emon::enctx::Cfg = &mut crate::emon::enctx::Cfg::new();
    let d: &mut crate::emon::enctx::Cfg = &mut crate::emon::enctx::Cfg::new();
    let e: &mut crate::emon::enctx::Cfg = &mut crate::emon::enctx::Cfg::new();
    t_parse(a, &crate::testport::text_blob("ocr=always\nfurniture=policy\nassets=none\nasset-signatures=off\nocr-scope=full")[..]);
    crate::testport::assert_eq(a.ocr, 2, "always");
    crate::testport::assert_eq(a.furn, 0, "policy");
    crate::testport::assert_eq(a.level, 0, "none");
    crate::testport::assert_eq(a.sigs, 0, "off");
    crate::testport::assert_eq(a.scope, 0, "full");
    t_parse(b, &crate::testport::text_blob("ocr=auto\nfurniture=keep\nassets=images")[..]);
    crate::testport::assert_eq(b.ocr, 1, "auto");
    crate::testport::assert_eq(b.furn, 1, "keep");
    crate::testport::assert_eq(b.level, 1, "images");
    t_parse(d, &crate::testport::text_blob("keep-evidence=0\nrecord=yes\njs-ocr=11")[..]);
    crate::testport::assert_eq(d.keep, 0, "a flag is 1 or nothing");
    crate::testport::assert_eq(d.rec, 0, "yes is not 1");
    crate::testport::assert_eq(d.jsocr, 0, "11 is not 1");
    t_parse(e, &crate::testport::text_blob("keep-evidence=1")[..]);
    crate::testport::assert_eq(e.keep, 1, "one");
}
