fn test_a_wrong_word_lists_the_words_from_the_table() {
    t_refused(0, &crate::testport::text_blob("ocr=sometimes")[..], "ocr is always, auto or never");
    t_refused(0, &crate::testport::text_blob("furniture=x")[..], "furniture is policy, keep or drop");
    t_refused(0, &crate::testport::text_blob("assets=x")[..], "assets is none, images or figures");
    t_refused(0, &crate::testport::text_blob("ocr-scope=x")[..], "ocr-scope is full or witness");
    t_refused(0, &crate::testport::text_blob("asset-signatures=maybe")[..], "asset-signatures is on or off");
    t_refused(0, &crate::testport::text_blob("ocr=")[..], "ocr is always, auto or never");
}
#[test]
fn test_a_wrong_number_is_refused_by_name() {
    t_refused(0, &crate::testport::text_blob("asset-dpi=abc")[..], "asset-dpi wants a number, not \"abc\"");
    t_refused(0, &crate::testport::text_blob("asset-dpi=")[..], "asset-dpi wants a number, not \"\"");
    t_refused(0, &crate::testport::text_blob("asset-dpi=-")[..], "asset-dpi wants a number, not \"-\"");
    t_refused(0, &crate::testport::text_blob("asset-dpi=12x")[..], "asset-dpi wants a number, not \"12x\"");
    t_refused(0, &crate::testport::text_blob("max-rounds=99999999999")[..], "max-rounds wants a number, not \"99999999999\"");
    t_refused(0, &crate::testport::text_blob("limit.pages=lots")[..], "limit.pages wants a number, not \"lots\"");
    t_refused(0, &crate::testport::text_blob("chunk=0")[..], "chunk is out of range 1..2147483647");
    t_refused(0, &crate::testport::text_blob("limit.pages=-1")[..], "limit.pages is out of range 0..2147483647");
    t_refused(0, &crate::testport::text_blob("limit.form-depth=33")[..], "limit.form-depth is out of range 0..32");
}
#[test]
fn test_an_unknown_key_or_a_line_without_a_value_is_refused_by_name() {
    t_refused(0, &crate::testport::text_blob("bogus=1")[..], "unknown option bogus");
    t_refused(0, &crate::testport::text_blob("ocr=auto\nbogus=1")[..], "unknown option bogus");
    t_refused(0, &crate::testport::text_blob("limit.nope=5")[..], "no limit named nope");
    t_refused(0, &crate::testport::text_blob("limit.=5")[..], "no limit named ");
    t_refused(0, &crate::testport::text_blob("novalue")[..], "option \"novalue\" has no value");
    t_refused(0, &crate::testport::text_blob("ocr=auto\nnovalue")[..], "option \"novalue\" has no value");
}
#[test]
fn test_a_limit_is_found_by_its_name() {
    let t: &mut crate::port::Cells = &mut crate::port::Cells::new();
    t_cps(t, &crate::testport::text_blob("ref-depth")[..]);
    crate::testport::assert_eq(cf_limit_find(t, 0, 9), 4, "ref-depth");
    crate::testport::assert_eq(cf_limit_find(t, 0, 8), -1, "a prefix of it");
    crate::testport::assert_eq(cf_limit_find(t, 4, 9), -1, "its tail");
    crate::testport::assert_eq(cf_key_find(t, 0, 9), -1, "not a key");
}
#[test]
fn test_the_limits_of_p10_4_are_found_by_their_names() {
    let t: &mut crate::port::Cells = &mut crate::port::Cells::new();
    t_cps(t, &crate::testport::text_blob("asset-placements")[..]);
    crate::testport::assert_eq(cf_limit_find(t, 0, 16), 13, "asset-placements");
    crate::port::cells_drop(t, 0);
    t_cps(t, &crate::testport::text_blob("ocr-requests")[..]);
    crate::testport::assert_eq(cf_limit_find(t, 0, 12), 10, "ocr-requests");
    crate::port::cells_drop(t, 0);
    t_cps(t, &crate::testport::text_blob("note-refs")[..]);
    crate::testport::assert_eq(cf_limit_find(t, 0, 9), 12, "note-refs");
}
